WITH parsed AS (SELECT id, plan, currency, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers WHERE currency IN ('EUR', 'THB', 'USD')) SELECT CASE WHEN entry_price >= 28 THEN 'PREMIUM' ELSE 'STANDARD' END AS entry_price_tier, APPROX_PERCENTILE(entry_price, ARRAY(0.25, 0.5, 0.75)) AS entry_price_quartiles, COUNT(*) FILTER (WHERE plan = 'enterprise') AS enterprise_rows, MIN(entry_price) AS min_entry_price, COUNT(*) AS cnt FROM parsed GROUP BY entry_price_tier HAVING COUNT(*) > 1
